.addEventListener('DOMContentLoaded', function () {

 function findCountry(callback) {
 let url = 'https://go1.aniview.com/api/adserver/tag/?AV_PUBLISHERID=55b88d4a181f465b3e8b4567&AV_CHANNELID=670f60cb59bfa2ec930a1430&sver=5&cb=' + Date.now();

 try {
 fetch(url)
 .then(function (response) { return response.json(); })
 .then(function (data) {
 let country = data?.data?.env?.device?.geo?.country || "";
 callback(country);
 })
 .catch(function () { callback(); });
 } catch (error) {
 callback();
 }
 }

 findCountry(function (country) {
 let scriptConfig = null;
 let path = window.location.pathname;

 // --- MEXICO IP LOGIC ---
 // Load tag ending in 22a08 for MEX IP on both US and Mexico pages
 if (country === 'MEX' && (path.includes('/usa/') || path

.includes('/usa/') || path.includes('/mexico/'))) {
 scriptConfig = {
 id: 'AV66d08ae8138b8fc4d1022a08',
 src: 'https://tg1.positive-ads.com/api/adserver/spt?AV_TAGID=66d08ae8138b8fc4d1022a08&AV_PUBLISHERID=6650fc74b41d249c590fe965'
 };
 }

 // --- USA IP LOGIC ---
 // 1. US IP on Mexico page
 else if (country === 'USA' && path.includes('/mexico/')) {
 scriptConfig = {
 id: 'AV680fac5f3f838c6d42016cc5',
 src: 'https://tg1.positive-ads.com/api/adserver/spt?AV_TAGID=680fac5f3f838c6d42016cc5&AV_PUBLISHERID=6650fc74b41d249c590fe965'
 };
 }
 // 2. US IP on US page
 else if (country === 'USA' && path.includes('/usa/')) {
 scriptConfig = {
 id: 'AV671a5e5cf27444928c016144',
 src: 'https://tg1.positive-ads

.positive-ads.com/api/adserver/spt?AV_TAGID=671a5e5cf27444928c016144&AV_PUBLISHERID=6650fc74b41d249c590fe965'
 };
 }

 // If no matching criteria are met, do not load any script
 if (!scriptConfig) return;
 setTimeout(function () {
 let sc = document.createElement('script');
 sc.id = scriptConfig.id;
 sc.async = true;
 sc.src = scriptConfig.src;
 (document.body || document.head).appendChild(sc);
 }, 500);
 });
});
